-- SVMA Intelligent AI Operations V2.3 - exact PDF source structure + Quality split
-- Run ONCE after V2.2/V2.2.1. It is written to be safe to re-run.

-- Quality roles.
do $$ begin
  alter type public.app_role add value if not exists 'quality_operator';
exception when duplicate_object then null; end $$;
do $$ begin
  alter type public.app_role add value if not exists 'quality_head';
exception when duplicate_object then null; end $$;

alter table public.parameter_master add column if not exists source_page int;
alter table public.parameter_master add column if not exists source_serial text;
alter table public.parameter_master add column if not exists source_group text;
alter table public.shift_sessions add column if not exists scope text not null default 'solvent';

create unique index if not exists parameter_source_identity_uq
on public.parameter_master(section_id,source_page,source_serial,name)
where source_page is not null and source_serial is not null;

-- Retire the earlier simplified source masters. Historical entries remain intact.
update public.parameter_master pm set active=false
from public.parameter_sections ps
where pm.section_id=ps.id and ps.module in ('solvent','quality','boiler')
  and coalesce(pm.source_ref,'') not like 'SOLVENT & BOILER(1).pdf%';

