insert into public.parameter_master(section_id,source_ref,source_page,source_serial,source_group,source_text,name,target_text,input_type,frequency,mandatory,alert_enabled,ticket_enabled,options,sort_order,active)
select ps.id,'SOLVENT & BOILER(1).pdf p'||src.source_page,src.source_page,src.source_serial,src.source_group,src.name,src.name,src.target_text,src.input_type,src.frequency,true,true,true,src.options,src.sort_order,true
from src join public.parameter_sections ps on ps.module=src.module and ps.name=src.section_name
on conflict(section_id,source_page,source_serial,name) where source_page is not null and source_serial is not null
 do update set source_group=excluded.source_group,source_text=excluded.source_text,target_text=excluded.target_text,input_type=excluded.input_type,frequency=excluded.frequency,options=excluded.options,sort_order=excluded.sort_order,active=true;

